/* @component: modal-popup */
(function () {
  if (window.__modPopupInit) return;
  window.__modPopupInit = true;
  document.addEventListener('click', function (e) {
    const closeBtn = e.target.closest('.mod__close');
    if (closeBtn) {
      const modal = closeBtn.closest('dialog') || document.querySelector('.mod-popup');
      if (modal && typeof modal.close === 'function') modal.close();
      return;
    }
    const openBtn = e.target.closest('.btn-open');
    if (openBtn) {
      const targetId = openBtn.getAttribute('data-target');
      const modal = targetId ? document.getElementById(targetId) : document.querySelector('.mod-popup');
      if (modal && typeof modal.showModal === 'function') modal.showModal();
    }
  });
  document.querySelectorAll('.mod-popup').forEach(function (modal) {
    if (modal.dataset.initialized === 'true') return;
    modal.dataset.initialized = 'true';
    modal.addEventListener('click', function (e) {
      if (e.target === modal && typeof modal.close === 'function') modal.close();
    });
  });
})();
/* @end: modal-popup */
